vertex:
#version 300 es

layout(location = 0) in vec2 vPosition;
out vec2 vdspv_fsin0;
layout(location = 1) in vec2 vTexCoords;
out vec4 vdspv_fsin1;
layout(location = 2) in vec4 vColor;

void main()
{
    gl_Position = vec4(vPosition, 0.0, 1.0);
    vdspv_fsin0 = vTexCoords;
    vdspv_fsin1 = vColor;
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

uniform highp sampler2D Atlas;

in highp vec2 vdspv_fsin0;
layout(location = 0) out highp vec4 fragColor;
in highp vec4 vdspv_fsin1;

void main()
{
    highp float coverage = texture(Atlas, vdspv_fsin0).x;
    fragColor = vec4(vdspv_fsin1.xyz, vdspv_fsin1.w * coverage);
}
